begin;
create extension if not exists pgtap with schema extensions;
select plan(17);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000090','demo-reset@test.invalid'),('10000000-0000-4000-8000-000000000091','demo-other@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000090','Reset test'),('20000000-0000-4000-8000-000000000091','Reset other');
insert into public.workspace_members(workspace_id,user_id,role) values ('20000000-0000-4000-8000-000000000090','10000000-0000-4000-8000-000000000090','owner'),('20000000-0000-4000-8000-000000000091','10000000-0000-4000-8000-000000000091','owner');
create temporary table ids(label text primary key, id uuid);
grant all on ids to authenticated, service_role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000090","role":"authenticated"}',true);
insert into ids select 'kept_case',(public.save_case_revision('20000000-0000-4000-8000-000000000090','{"title":"Kept seed","template":"product_delivery","outcome":"unknown","problem":"Risk","context":"Team","constraints":"None","approach":"Canary","observedOutcome":"Unknown","lessons":"Monitor","deliverable":"Feature","changeScope":"Checkout","deploymentConditions":"Rollback","conceptIds":[],"sources":[]}')->>'caseId')::uuid;
insert into ids select 'kept_rev',(select latest_revision_id from public.cases where id=(select id from ids where label='kept_case'));
insert into ids select 'extra_case',(public.save_case_revision('20000000-0000-4000-8000-000000000090','{"title":"Visitor case","template":"product_delivery","outcome":"unknown","problem":"Risk","context":"Team","constraints":"None","approach":"Canary","observedOutcome":"Unknown","lessons":"Monitor","deliverable":"Feature","changeScope":"Checkout","deploymentConditions":"Rollback","conceptIds":[],"sources":[]}')->>'caseId')::uuid;
insert into ids select 'extra_rev',(select latest_revision_id from public.cases where id=(select id from ids where label='extra_case'));
select public.publish_case_revision((select id from ids where label='kept_rev'),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions r,jsonb_each_text(r.content) where r.id=(select id from ids where label='kept_rev') and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);
select public.publish_case_revision((select id from ids where label='extra_rev'),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions r,jsonb_each_text(r.content) where r.id=(select id from ids where label='extra_rev') and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);
select public.link_cases((select id from ids where label='extra_case'),(select id from ids where label='kept_case'),'related_to','Visitor link',false);
select public.archive_case((select id from ids where label='kept_case'));
select public.create_conversation('20000000-0000-4000-8000-000000000090','30000000-0000-4000-8000-000000000090');
select set_config('test.turn',public.save_conversation_turn('30000000-0000-4000-8000-000000000090','40000000-0000-4000-8000-000000000090','How can we release?','{"template":"product_delivery","version":1,"objective":"Release","context":"Small team","hardConstraints":[],"conceptIds":[],"unknowns":""}'::jsonb)::text,true);
select public.admit_conversation_analysis(current_setting('test.turn')::uuid,'50000000-0000-4000-8000-000000000090',2,90000);
select public.finish_analysis((select id from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000090'),'complete','{"version":2,"text":"A general answer.","citations":[]}','[]',null,null);
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000091","role":"authenticated"}',true);
insert into ids select 'other_case',(public.save_case_revision('20000000-0000-4000-8000-000000000091','{"title":"Other workspace case","template":"product_delivery","outcome":"unknown","problem":"Risk","context":"Team","constraints":"None","approach":"Canary","observedOutcome":"Unknown","lessons":"Monitor","deliverable":"Feature","changeScope":"Checkout","deploymentConditions":"Rollback","conceptIds":[],"sources":[]}')->>'caseId')::uuid;
insert into ids select 'other_rev',(select latest_revision_id from public.cases where id=(select id from ids where label='other_case'));
select public.publish_case_revision((select id from ids where label='other_rev'),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions r,jsonb_each_text(r.content) where r.id=(select id from ids where label='other_rev') and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);
select public.create_conversation('20000000-0000-4000-8000-000000000091','30000000-0000-4000-8000-000000000091');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000090","role":"authenticated"}',true);
select throws_ok($$select public.reset_demo_workspace('20000000-0000-4000-8000-000000000090'::uuid,array[(select id from ids where label='kept_case')])$$,'42501',null,'members cannot reset a workspace');
reset role;
set local role anon;
select throws_ok($$select public.reset_demo_workspace('20000000-0000-4000-8000-000000000090'::uuid,'{}'::uuid[])$$,'42501',null,'anonymous cannot reset a workspace');
reset role;
set local role service_role;
create temporary table reset_result(result jsonb);
grant all on reset_result to service_role;
insert into reset_result select public.reset_demo_workspace('20000000-0000-4000-8000-000000000090'::uuid,array[(select id from ids where label='kept_case')]);
reset role;
select is((select count(*) from public.cases where workspace_id='20000000-0000-4000-8000-000000000090'),1::bigint,'only the kept case remains');
select is((select id from public.cases where workspace_id='20000000-0000-4000-8000-000000000090'),(select id from ids where label='kept_case'),'the kept case is the seed case');
select is((select published_revision_id from public.cases where workspace_id='20000000-0000-4000-8000-000000000090'),(select id from ids where label='kept_rev'),'the kept published revision remains');
select is((select count(*) from public.case_sections where revision_id=(select id from ids where label='kept_rev')),9::bigint,'the kept case keeps its indexed sections');
select is((select count(*) from public.case_revisions where workspace_id='20000000-0000-4000-8000-000000000090'),1::bigint,'extra revisions are gone');
select is((select count(*) from public.case_sections where workspace_id='20000000-0000-4000-8000-000000000090'),9::bigint,'extra sections are gone');
select is((select count(*) from public.case_links where workspace_id='20000000-0000-4000-8000-000000000090'),0::bigint,'links to removed cases are gone');
select is((select count(*) from public.conversations where workspace_id='20000000-0000-4000-8000-000000000090'),0::bigint,'conversations are gone');
select is((select count(*) from public.conversation_turns where workspace_id='20000000-0000-4000-8000-000000000090'),0::bigint,'turns are gone');
select is((select count(*) from public.analysis_runs where workspace_id='20000000-0000-4000-8000-000000000090'),0::bigint,'runs are gone');
select is((select count(*) from public.briefs where workspace_id='20000000-0000-4000-8000-000000000090'),0::bigint,'briefs are gone');
select is((select count(*) from public.cases where workspace_id='20000000-0000-4000-8000-000000000091'),1::bigint,'another workspace keeps its cases');
select is((select count(*) from public.conversations where workspace_id='20000000-0000-4000-8000-000000000091'),1::bigint,'another workspace keeps its conversations');
select is((select lifecycle from public.cases where id=(select id from ids where label='kept_case')),'active','a seed case archived by a visitor is restored');
select is((select (result->>'cases')::int from reset_result),1,'the result counts removed cases');
select * from finish();
rollback;
